fn is_reparse_shape(is_symlink: bool, file_attributes: u32) -> bool {
    const FILE_ATTRIBUTE_REPARSE_POINT: u32 = 0x0400;
    is_symlink || file_attributes & FILE_ATTRIBUTE_REPARSE_POINT != 0
}

#[cfg(windows)]
fn current_user_local_app_data() -> Result<PathBuf, ()> {
    use std::ptr::null_mut;

    use windows_sys::Win32::UI::Shell::{FOLDERID_LocalAppData, SHGetKnownFolderPath};

    let mut raw = null_mut();
    let result = unsafe { SHGetKnownFolderPath(&FOLDERID_LocalAppData, 0, null_mut(), &mut raw) };
    if result < 0 || raw.is_null() {
        return Err(());
    }
    let raw = KnownFolderBuffer(raw);
    let mut length = 0_usize;
    while length <= 32_767 && unsafe { *raw.0.add(length) } != 0 {
        length += 1;
    }
    if length == 0 || length > 32_767 {
        return Err(());
    }
    let path = PathBuf::from(OsString::from_wide(unsafe {
        std::slice::from_raw_parts(raw.0, length)
    }));
    drop(raw);
    if !path.is_absolute() {
        return Err(());
    }
    let text = path.as_os_str().to_string_lossy();
    if text.starts_with("\\\\") || text.starts_with("//") || text.starts_with("\\\\?") {
        return Err(());
    }
    Ok(path)
}

#[cfg(windows)]
struct KnownFolderBuffer(*mut u16);

#[cfg(windows)]
impl Drop for KnownFolderBuffer {
    fn drop(&mut self) {
        if !self.0.is_null() {
            unsafe {
                windows_sys::Win32::System::Com::CoTaskMemFree(self.0.cast());
            }
        }
    }
}

