        return Err(());
    }
    let descriptor = LocalSecurityDescriptor(descriptor);
    if dacl.is_null() || unsafe { IsValidAcl(dacl) } == 0 {
        return Err(());
    }
    let current_user_sid = current_windows_user_sid()?;
    if !unsafe { windows_owner_matches(owner, &current_user_sid) }? {
        return Ok(CandidatePrivateRootStatus::OwnerMismatch);
    }
    let status = unsafe { classify_windows_dacl(dacl, &current_user_sid) }?;
    drop(descriptor);
    Ok(status)
}

#[cfg(windows)]
unsafe fn windows_owner_matches(
    owner: windows_sys::Win32::Security::PSID,
    current_user_sid: &OwnedSid,
) -> Result<bool, ()> {
    use windows_sys::Win32::Security::{EqualSid, IsValidSid};

    if owner.is_null() || unsafe { IsValidSid(owner) } == 0 {
        return Err(());
    }
    Ok(unsafe { EqualSid(owner, current_user_sid.as_psid()) } != 0)
}

